package ai.eva.android.probe;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.PixelFormat;import android.graphics.drawable.GradientDrawable;import android.view.accessibility.AccessibilityNodeInfo;import org.json.*;import java.util.*;
/** Reports actual phone-tool turns independently of the WebView lifecycle. */
final class PhoneTaskReport {
 static final Handler ui=new Handler(Looper.getMainLooper());static final Map<String,Run> runs=new HashMap<>();
 static class Run{String thread,turn,answer="",lastPackage="";boolean done,dismissed;long generation;Run(String t,String id){thread=t;turn=id;generation=PhoneAccessibility.generation;}}
 static View pill;static WindowManager window;static Runnable dismiss;static String shownThread="";
 static boolean enabled(Context c,String key){return c.getSharedPreferences("eva-phone",0).getBoolean(key,true);}
 static synchronized Run begin(Context c,String thread,String turn,String action){Run r=runs.get(thread);if(r==null||!r.turn.equals(turn)||r.done){r=new Run(thread,turn);runs.put(thread,r);}final Run current=r;ui.post(()->{if(!current.done&&current.generation==PhoneAccessibility.generation){notify(c,current,"Eva 正在处理",actionLabel(action),false);show(c,current,actionLabel(action),false);}});return r;}
 static String actionLabel(String a){switch(a){case "open_gallery":return "正在打开相册";case "open_app":return "正在打开应用";case "observe":return "正在读取页面";case "screenshot":return "正在查看画面";case "click":return "正在点击";case "input":return "正在输入";case "scroll":case "gesture":return "正在浏览页面";case "shell":return "正在执行手机命令";default:return "正在处理手机任务";}}
 static synchronized void observed(String thread,JSONObject result){Run r=runs.get(thread);if(r!=null&&result.has("package"))r.lastPackage=result.optString("package");}
 static synchronized void event(Context c,JSONObject row){JSONObject p=row.optJSONObject("params");if(p==null)return;String thread=p.optString("threadId");Run r=runs.get(thread);if(r==null||r.done)return;String method=row.optString("method");if(method.equals("item/completed")){JSONObject item=p.optJSONObject("item");if(item!=null&&item.optString("type").equals("agentMessage")&&!item.optString("phase").equals("commentary"))r.answer=item.optString("text","");}
  if(method.endsWith("requestApproval")||method.equals("tool/requestUserInput")){ui.post(()->{notify(c,r,"Eva 需要你的确认","点击返回任务继续处理",true);show(c,r,"需要你的确认 · 点击返回",true);});}
  if(method.equals("turn/completed")){JSONObject t=p.optJSONObject("turn");if(t==null||!t.optString("id").equals(r.turn))return;r.done=true;JSONArray items=t.optJSONArray("items");if(items!=null)for(int n=0;n<items.length();n++){JSONObject item=items.optJSONObject(n);if(item!=null&&item.optString("type").equals("agentMessage")&&!item.optString("phase").equals("commentary"))r.answer=item.optString("text",r.answer);}String status=t.optString("status");ui.post(()->finish(c,r,status));runs.remove(thread);}
 }
 static String title(String state){return state.equals("failed")?"Eva 任务未完成":state.equals("interrupted")?"Eva 任务已停止":"Eva 处理结束";}
 static Intent target(Context c,String thread){return new Intent(c,ShellActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP).putExtra("phone-thread",thread);}
 static void open(Context c,String thread){hide();try{Context launcher=PhoneAccessibility.live!=null?PhoneAccessibility.live:c;launcher.startActivity(target(c,thread));}catch(Exception ignored){}}
 static void finish(Context c,Run r,String state){String heading=title(state);notify(c,r,heading,"结果已更新，点击返回发起任务的对话",true);String summary=r.answer.replaceAll("\\s+"," ").trim();if(summary.length()>80)summary=summary.substring(0,80)+"…";show(c,r,heading+(summary.isEmpty()?" · 点击查看":" · "+summary),true);
  if(enabled(c,"returnAfterTask")&&PhoneAccessibility.armed&&r.generation==PhoneAccessibility.generation&&!((KeyguardManager)c.getSystemService(Context.KEYGUARD_SERVICE)).isKeyguardLocked()){PhoneAccessibility service=PhoneAccessibility.live;if(service!=null){AccessibilityNodeInfo root=service.getRootInActiveWindow();String pkg=root==null?"":String.valueOf(root.getPackageName());if(root!=null)root.recycle();if(!r.lastPackage.isEmpty()&&pkg.equals(r.lastPackage)&&!pkg.equals(c.getPackageName()))open(c,r.thread);}}
 }
 static void notify(Context c,Run r,String title,String text,boolean finished){try{NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("eva-phone-task","手机任务进度与结果",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,r.thread.hashCode(),target(c,r.thread),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=new Notification.Builder(c,"eva-phone-task").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle(title).setContentText(text).setContentIntent(open).setVisibility(Notification.VISIBILITY_PRIVATE).setOnlyAlertOnce(!finished).setOngoing(!finished).setAutoCancel(finished).setCategory(Notification.CATEGORY_PROGRESS);if(!finished)b.setProgress(0,0,true);if(Build.VERSION.SDK_INT>=36&&!finished){Bundle extras=new Bundle();extras.putBoolean("android.requestPromotedOngoing",true);b.addExtras(extras).setShortCriticalText("手机任务");}nm.notify(2021,b.build());}catch(Exception ignored){}}
 static void show(Context c,Run r,String text,boolean finished){hide();if(r.dismissed||!enabled(c,"taskPill")||PhoneAccessibility.live==null||((KeyguardManager)c.getSystemService(Context.KEYGUARD_SERVICE)).isKeyguardLocked())return;PhoneAccessibility service=PhoneAccessibility.live;float density=service.getResources().getDisplayMetrics().density;LinearLayout box=new LinearLayout(service);box.setGravity(Gravity.CENTER_VERTICAL);box.setPadding((int)(16*density),(int)(9*density),(int)(10*density),(int)(9*density));GradientDrawable background=new GradientDrawable();background.setColor(0xf020242a);background.setCornerRadius(24*density);box.setBackground(background);TextView label=new TextView(service);label.setText(text);label.setTextSize(13);label.setTextColor(0xfff5f7fa);label.setMaxLines(finished?2:1);label.setEllipsize(android.text.TextUtils.TruncateAt.END);box.addView(label,new LinearLayout.LayoutParams(0,-2,1));label.setOnClickListener(v->open(c,r.thread));TextView close=new TextView(service);close.setText("关闭");close.setTextColor(0xffb9c2cf);close.setTextSize(11);close.setPadding((int)(12*density),0,(int)(8*density),0);close.setOnClickListener(v->{r.dismissed=true;hide();});box.addView(close);box.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);WindowManager.LayoutParams params=new WindowManager.LayoutParams(Math.min((int)(340*density),service.getResources().getDisplayMetrics().widthPixels-(int)(32*density)),-2,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;params.y=(int)(8*density);try{window=(WindowManager)service.getSystemService(Context.WINDOW_SERVICE);window.addView(box,params);pill=box;shownThread=r.thread;if(finished){dismiss=()->hide();ui.postDelayed(dismiss,12000);}}catch(Exception ignored){pill=null;}}
 static void hide(){if(dismiss!=null){ui.removeCallbacks(dismiss);dismiss=null;}if(pill!=null&&window!=null)try{window.removeView(pill);}catch(Exception ignored){}pill=null;}
  static void preview(Context c){begin(c,"","preview","observe");ui.postDelayed(()->{try{event(c,new JSONObject().put("method","item/completed").put("params",new JSONObject().put("threadId","").put("item",new JSONObject().put("type","agentMessage").put("text","这是任务完成提示预览，实际任务结束后会显示结果摘要。"))));event(c,new JSONObject().put("method","turn/completed").put("params",new JSONObject().put("threadId","").put("turn",new JSONObject().put("id","preview").put("status","completed"))));}catch(Exception ignored){}},2000);}
 static synchronized void failAll(Context c){for(Run r:runs.values()){r.done=true;ui.post(()->finish(c,r,"failed"));}runs.clear();}
 static void close(){ui.post(PhoneTaskReport::hide);}
}
